//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn document_template_clone_nested_owners_interfaces_kind_and_ordinary_children_are_real(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var ns='http://www.w3.org/1999/xhtml',html=document.implementation.createHTMLDocument('kept'),xml=document.implementation.createDocument('urn:original','p:Root'),generic=new Document();generic.appendChild(generic.createElement('Root'));
for(var source of [html,xml,generic]){var parent=source===html?source.body:source.documentElement,host=source.createElementNS(ns,'template');parent.appendChild(host);var original=host.content,owner=original.ownerDocument,ordinary=source.createElementNS(ns,'span');ordinary.textContent='ordinary';host.appendChild(ordinary);var nested=owner.createElementNS(ns,'template'),leaf=owner.createElementNS(ns,'span'),attr=owner.createAttribute('MiXeD');attr.value='kept';leaf.setAttributeNode(attr);leaf.appendChild(owner.createTextNode('held'));original.appendChild(leaf);original.appendChild(nested);nested.content.appendChild(owner.createComment('nested'));var copy=source.cloneNode(true),copiedParent=source===html?copy.body:copy.documentElement,copied=copiedParent.firstChild,content=copied.content,associated=content.ownerDocument,inner=content.lastChild;
if(copy===source||copy instanceof XMLDocument!==(source===xml)||copied===host||copied.ownerDocument!==copy||copied.firstChild===ordinary||copied.firstChild.ownerDocument!==copy||copied.firstChild.textContent!=='ordinary'||content===original||content.parentNode!==null||associated===copy||associated===owner||associated instanceof XMLDocument||associated.contentType!=='application/xml'||associated.createAttribute('MiXeD').name!==(source===html?'mixed':'MiXeD')||inner.ownerDocument!==associated||inner.content===nested.content||inner.content.ownerDocument!==associated||inner.content.firstChild.ownerDocument!==associated||inner.content.firstChild.data!=='nested')throw 'distinct cloned document owner and nested content records';var copiedLeaf=content.firstChild;if(copiedLeaf===leaf||copiedLeaf.ownerDocument!==associated||copiedLeaf.firstChild.ownerDocument!==associated||copiedLeaf.firstChild.data!=='held'||copiedLeaf.getAttributeNode(attr.name)===attr||copiedLeaf.getAttributeNode(attr.name).ownerDocument!==associated)throw 'actual descendant and Attr ownership';copiedLeaf.firstChild.data='changed';inner.content.firstChild.data='changed';if(leaf.firstChild.data!=='held'||nested.content.firstChild.data!=='nested'||host.content!==original||host.firstChild!==ordinary)throw 'source contents and ordinary children unchanged';var sibling=copy.createElementNS(ns,'template');if(sibling.content.ownerDocument!==associated)throw 'clone associated owner cache';var shallow=source.cloneNode(false);if(shallow.documentElement!==null||shallow.doctype!==null||shallow===source||shallow instanceof XMLDocument!==(source===xml))throw 'shallow document has no cloned templates';}
"#);
}
#[test]
fn document_template_clone_lazy_nested_loaded_contents_ignore_author_getter_before_identity_planning(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var source=document.implementation.createHTMLDocument('lazy source'),host=source.createElement('template');source.body.appendChild(host);host.innerHTML='<span id="held">loaded</span><template><b>nested</b></template>';var calls=0,get=Object.getOwnPropertyDescriptor(HTMLTemplateElement.prototype,'content').get;Object.defineProperty(host,'content',{get:function(){calls++;throw 'author getter';}});var copy=source.cloneNode(true),cloned=copy.body.firstChild,original=get.call(host),content=cloned.content;if(calls||cloned===host||content===original||content.firstChild===original.firstChild||content.firstChild.textContent!=='loaded'||content.lastChild.content.firstChild.textContent!=='nested'||content.lastChild.content.ownerDocument!==content.ownerDocument||cloned.ownerDocument!==copy||content.ownerDocument===copy||content.ownerDocument===original.ownerDocument)throw 'lazy source preparation uses native getter before clone IDs';content.firstChild.setAttribute('id','changed');content.firstChild.firstChild.data='changed';if(original.firstChild.id!=='held'||original.firstChild.textContent!=='loaded'||calls)throw 'loaded snapshot independence';
"#);
}
#[test]
fn document_template_clone_refusal_preserves_source_views_records_and_recovers(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var source=new Document();source.appendChild(source.createElementNS('http://www.w3.org/1999/xhtml','template'));var host=source.documentElement,original=host.content,owner=original.ownerDocument,leaf=owner.createTextNode('held');original.appendChild(leaf);var view=original.childNodes,watch=new MutationObserver(function(){});watch.observe(original,{subtree:true,childList:true,characterData:true});");let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);let limit=page.state.retained_limit;page.state.retained_limit=page.state.retained;assert_eq!(page.console_eval(&mut doc,&mut forms,"source.cloneNode(true);").errors,1);assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);page.state.retained_limit=limit;run(&mut doc,&mut forms,&mut page,"if(host.content!==original||original.ownerDocument!==owner||view.length!==1||view[0]!==leaf||leaf.data!=='held'||watch.takeRecords().length)throw 'refusal preserves source';var copy=source.cloneNode(true);if(copy.documentElement===host||copy.documentElement.content===original||copy.documentElement.content.firstChild===leaf||copy.documentElement.content.firstChild.data!=='held'||copy.documentElement.content.ownerDocument===owner)throw 'fresh independent template document recovery';");assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());
}

#[test]
fn document_template_clone_saved_child_method_origin_rejects_before_publication(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var source=new Document();source.appendChild(source.createElementNS('http://www.w3.org/1999/xhtml','template'));source.documentElement.content.appendChild(source.documentElement.content.ownerDocument.createTextNode('held'));var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Node.prototype.cloneNode,copy=saved.call(source,true);if(copy===source||copy.documentElement.content.firstChild.data!=='held')throw 'genuine saved clone receiver';");page.set_location(&crate::navigation::address("https://other-document-clone.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(source,true);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(source.documentElement.content.firstChild.data!=='held'||copy.documentElement.content.firstChild.data!=='held')throw 'source and clone unchanged by origin refusal';");
}

#[test]
fn document_template_clone_inert_native_control_data_does_not_bypass_import_hooks(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var source=document.implementation.createHTMLDocument('inert'),host=source.createElement('template');source.body.appendChild(host);host.innerHTML='<span>prefix</span><input value=held>';var copy=source.cloneNode(true),cloned=copy.body.firstChild,content=cloned.content,target=new Document(),caught=false;if(content.childNodes.length!==2||content.lastChild.localName!=='input'||content.lastChild.getAttribute('value')!=='held'||content.lastChild.ownerDocument!==content.ownerDocument)throw 'native control remains genuine inert data';");let before=(doc.nodes.len(),page.state.dom_commits);run(&mut doc,&mut forms,&mut page,"try{target.importNode(cloned,true);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||target.documentElement!==null||target.childNodes.length||content.childNodes.length!==2||host.content.childNodes.length!==2||content.lastChild===host.content.lastChild)throw 'native import hook guard precedes destination prefix';");assert_eq!((doc.nodes.len(),page.state.dom_commits),before);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
